prog='''import numpy as np

def transform(grid):
    """Output = the corrupted 8-block, refilled. The full grid is a 30x30 crop of a
    32x32 pattern with double mirror symmetry (pair sums 31: i<->31-i, j<->31-j for
    indices >=1; rows/cols 0-1 are orphan stripes whose partners are cropped away).
    Refill: (i,j) -> h-partner (i,31-j) or v-partner (31-i,j). Cells whose partners are
    also hidden are resolved by the generator rule that the 2x2-block grid
    (block (b_i,b_j) = cells rows 2b_i..2b_i+1, cols 2b_j..2b_j+1) is constant along
    the anti-diagonal b_i + b_j == 7."""
    A = np.array(grid)
    H, W = A.shape
    out = A.copy().astype(int)
    for i in range(H):
        for j in range(W):
            if out[i, j] == 8:
                if 31 - j < W and A[i, 31 - j] != 8:
                    out[i, j] = A[i, 31 - j]
                elif 31 - i < H and A[31 - i, j] != 8:
                    out[i, j] = A[31 - i, j]
    for i in range(H):
        for j in range(W):
            if out[i, j] == 8:
                bi, bj, ci, cj = i // 2, j // 2, i % 2, j % 2
                for r in range(8):
                    c = 7 - bi - bj - r
                    if 0 <= r < 8 and 0 <= c < 8:
                        r0, c0 = 2 * r, 2 * c
                        if r0 + 1 < H and c0 + 1 < W:
                            blk = out[r0:r0 + 2, c0:c0 + 2]
                            if 8 not in blk:
                                out[i, j] = blk[ci, cj]
                                break
    rs, cs = np.where(A == 8)
    return [list(map(int, r)) for r in out[rs.min():rs.max() + 1, cs.min():cs.max() + 1]]
'''
